import { Redirect } from "react-router-dom";
import { decodeToken, getUserRole } from "../utils/auth";

const ProtectedRoute = ({ children, role }) => {
    const payload = decodeToken();
    
    console.log("ProtectedRoute - payload:", payload);
    console.log("ProtectedRoute - role required:", role);

    if (!payload) return <Redirect to={`/${role}/login`} />;
    if (role && role !== decodeToken(getUserRole())) {
        console.log("Role mismatch - payload.role:", payload.role);
        return <Redirect to="/" />;
    }

    return children;
};

export default ProtectedRoute;
